def _indice_citacao_por_estrutura(corpo_bruto: str) -> int | None:
    """Índice (no texto já limpo) do parágrafo que é a citação bíblica.

    Usa a estrutura do markdown BRUTO: procura a seção "## Texto" e conta
    quantos parágrafos existem até a citação. Como o _limpar_md remove os
    headers, o índice é calculado sobre a contagem de parágrafos do corpo
    limpo, mas ancorado na posição da citação no corpo bruto.
    """
    # No corpo bruto, o bloco de citação é o primeiro "> " com aspas após "## Texto"
    linhas = corpo_bruto.split("\n")
    try:
        i_texto = next(i for i, l in enumerate(linhas)
                       if l.strip().lower() in ("## texto", "# texto"))
    except StopIteration:
        return None
    # conta parágrafos (separados por linha em branco) do início do corpo
